// Puts the desk's answer next to the customer row, so "IF: Human Handoff?"
// keeps working unchanged: handoff = true while a human has this customer.
const row = $('Postgres: Upsert Customer').item.json;
const desk = $json || {};
return { json: Object.assign({}, row, {
  desk_active: desk.human_active === true,
  handoff: row.handoff === true || desk.human_active === true,
}) };
